  FT["PH-H3866"] = {"id":"PH-H3866","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4905_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第3259号共和国法（即《授予International Communications Corporation建立国内无线电通信、无线电话、广播与电视广播电台特许权》）的法案","en":"An Act to Amend Republic Act Numbered Thirty-Two Hundred and Fifty-Nine, Entitled \"An Act Granting the International Communications Corporation a Franchise to Establish Radio Stations for Domestic Radio Telecommunications, Radiophone, Broadcasting and Telecasting\"","orig":"An Act to Amend Republic Act Numbered Thirty-Two Hundred and Fifty-Nine, Entitled \"An Act Granting the International Communications Corporation a Franchise to Establish Radio Stations for Domestic Radio Telecommunications, Radiophone, Broadcasting and Telecasting\"","vi":"Đạo luật sửa đổi Đạo luật Cộng hòa số 3259","th":"พระราชบัญญัติแก้ไขเพิ่มเติมพระราชบัญญัติแห่งสาธารณรัฐที่ 3259","id":"Undang-Undang mengubah Undang-Undang Republik No. 3259","ms":"Akta meminda Akta Republik No. 3259"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 4905","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4905_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3866-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section four of Republic Act Numbered Three thousand two hundred fifty-nine is hereby amended to read as follows:\n\"Sec. 4. This franchise shall continue for a period of twenty-five years from the date the first of said stations shall be placed in operation, and is granted upon the express condition that same shall be void unless the construction of said station be begun within two years from the date of the approval of this amendatory Act and be completed within four years from said date.\""}},{"id":"PH-H3866-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Republic Act Numbered Thirty-Two Hundred and Fifty-Nine, Entitled \"An Act Granting the International Communications Corporation a Franchise to Establish Radio Stations for Domestic Radio Telecommunications, Radiophone, Broadcasting and Telecasting\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3867"] = {"id":"PH-H3867","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4906_1967.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在伊莎贝拉省设立San Guillermo市镇的法案","en":"An Act Creating the Municipality of San Guillermo in the Province of Isabela","orig":"An Act Creating the Municipality of San Guillermo in the Province of Isabela","vi":"Đạo luật thành lập Thị trấn San Guillermo tại Tỉnh Isabela","th":"พระราชบัญญัติจัดตั้งเทศบาล San Guillermo ในจังหวัด Isabela","id":"Undang-Undang membentuk Kotamadya San Guillermo di Provinsi Isabela","ms":"Akta mewujudkan Perbandaran San Guillermo di Wilayah Isabela"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4906","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4906_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3867-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barrios Anunang, Calawagan, Colorado, Dipacamo, Edcor, Guam, Nakar, Palawan, Progreso, San Francisco, San Mariano Norte, San Mariano Sur, Villa Rose, Villa Sanchez, and Villa Teresita in the Municipality of Angadanan; and barrios Aringay, Dingading, San Francisco, and Sinalugan in the Municipality of Echague, all in the Province of Isabela, are separated from said municipalities and constituted into a distinct and independent municipality, to be known as the Municipality of San Guillermo, same province. The seat of government of the new municipality shall be in the present site of Barrio Edcor."}},{"id":"PH-H3867-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor and councilors of the new municipality shall be elected in the next general elections for the local officials."}},{"id":"PH-H3867-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of San Guillermo in the Province of Isabela","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3868"] = {"id":"PH-H3868","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4907_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第466号联邦法第147条（即《国家国内税收法典》）的法案","en":"An Act to Further Amend Section One Hundred and Forty-Seven of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code","orig":"An Act to Further Amend Section One Hundred and Forty-Seven of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code","vi":"Đạo luật sửa đổi thêm Điều 147 của Đạo luật Thịnh vượng chung số 466 (Bộ luật Thuế nội địa)","th":"พระราชบัญญัติแก้ไขเพิ่มเติมอีกมาตรา 147 แห่งพระราชบัญญัติเครือรัฐที่ 466 (ประมวลรัษฎากร)","id":"Undang-Undang mengubah lagi Pasal 147 Undang-Undang Persemakmuran No. 466 (Kitab Undang-Undang Pajak Dalam Negeri)","ms":"Akta meminda lagi Seksyen 147 Akta Komanwel No. 466 (Kanun Hasil Dalam Negeri)"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 4907","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4907_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3868-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one hundred and forty-seven of Commonwealth Act Numbered Four hundred and sixty-six, otherwise known as the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Sec. 147. Specific Tax on Playing Cards. — (a) On each pack of cards regardless of the size thereof containing not more than sixty cards, there shall be collected a tax of three pesos.\n\"(b) On each pack containing more than sixty cards, there shall be collected the tax established in subsection (a) and a proportionate additional tax on the number in excess of sixty: Provided, However, That the maximum amount that shall be collected on one pack shall not exceed seven pesos.\""}},{"id":"PH-H3868-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further Amend Section One Hundred and Forty-Seven of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3869"] = {"id":"PH-H3869","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4908_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"要求法院法官迅速审理受害方即将离境且归期不定的刑事案件的法案","en":"An Act Requiring Judges of Courts to Speedily Try Criminal Cases Wherein the Offended Party is a Person About to Depart from the Philippines with No Definite Date of Return","orig":"An Act Requiring Judges of Courts to Speedily Try Criminal Cases Wherein the Offended Party is a Person About to Depart from the Philippines with No Definite Date of Return"},"level":"law","status":"active","topics":["criminal","judiciary"],"docNumber":"Republic Act No. 4908","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4908_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3869-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of existing laws, executive order, rule or regulation to the contrary notwithstanding, the trial of criminal cases wherein the offended party is a person who is about to depart from the Philippines without a definite date of return, shall take precedence over all other cases before our courts, except election and habeas corpus cases. The trial in these cases shall commence within three days from the date the accused is arraigned and no postponement of the initial hearing shall be granted except on the ground of illness on the part of the accused, or other grounds beyond the control of the accused."}},{"id":"PH-H3869-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967"}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Requiring Judges of Courts to Speedily Try Criminal Cases Wherein the Offended Party is a Person About to Depart from the Philippines with No Definite Date of Return","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3870"] = {"id":"PH-H3870","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4909_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"免除Gemma Cruz小姐作为国际小姐所得一万美元奖金的所得税的法案","en":"An Act Exempting from Income Tax the Ten Thousand Dollars Prize of Miss Gemma Cruz as Miss International","orig":"An Act Exempting from Income Tax the Ten Thousand Dollars Prize of Miss Gemma Cruz as Miss International"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 4909","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4909_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3870-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The ten thousand dollars prize of Miss Gemma Cruz as Miss International, donated by her to Boys Town, shall not be included in gross income and shall be exempt from income tax, any provision of the National International Revenue Code to the contrary notwithstanding."}},{"id":"PH-H3870-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967"}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Exempting from Income Tax the Ten Thousand Dollars Prize of Miss Gemma Cruz as Miss International","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3871"] = {"id":"PH-H3871","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4910_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"对《一般银行法》的修改","en":"An Act Amending Section Twenty-Seven of Republic Act Numbered Three Hundred Thirty-Seven, Otherwise Known as the General Banking Act","orig":"An Act Amending Section Twenty-Seven of Republic Act Numbered Three Hundred Thirty-Seven, Otherwise Known as the General Banking Act","vi":"Đạo luật sửa đổi Điều 27 của Đạo luật Cộng hòa số 337 (General Banking Act)","th":"พระราชบัญญัติแก้ไขเพิ่มเติมมาตรา 27 แห่งพระราชบัญญัติแห่งสาธารณรัฐที่ 337 (General Banking Act)","id":"Undang-Undang mengubah Pasal 27 Undang-Undang Republik No. 337 (General Banking Act)","ms":"Akta meminda Seksyen 27 Akta Republik No. 337 (General Banking Act)"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 4910","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4910_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3871-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section twenty-seven of Republic Act Numbered three hundred thirty-seven, otherwise known as the General Banking Act, is hereby amended to read as follows:\n\"Sec. 27. Any commercial bank organized under the laws of the Philippines may, with the prior approval of the Monetary Board, establish branches in the Philippines or branches and agencies outside the Philippines, and the bank shall be responsible for all business conducted in such branches to the same extent and in the same manner as though such business had all been conducted in the head office. The hours and times during which all types of banks with their branches and extension offices are to conduct and transact their business shall not exceed eight hours a day to be selected by the banking institution concerned between eight o’clock in the morning to eight o’clock in the evening, which time shall be reported to the Monetary Board.\n\"For the purposes of this Act, a bank and its branches shall be treated as a unit.\""}},{"id":"PH-H3871-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55"};
  FT["PH-H3872"] = {"id":"PH-H3872","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4911_1967.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"使菲律宾大学公共管理学院成为更有效培训机构的法案","en":"An Act Making the College of Public Administration of the University of the Philippines a More Effective Training Institution","orig":"An Act Making the College of Public Administration of the University of the Philippines a More Effective Training Institution"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4911","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4911_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3872-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In order to carry out the objectives of the College of Public Administration, University of the Philippines as an established institution involved in the endeavor in improving Philippine public administration, modernizing the administrative system and increasing the capacity of the governmental machinery to promote social and economic development, there is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of two million five hundred thousand pesos annually for two years for the construction or acquisition of the necessary building and other physical facilities and equipment of the said College of Public Administration of the University of the Philippines beginning in the fiscal year nineteen hundred sixty-seven and nineteen hundred sixty-eight: Provided, That the sum of six hundred fifty thousand pesos is appropriated for the operating expenses of the College for the fiscal year nineteen hundred sixty-seven and nineteen hundred sixty-eight: Provided, further, That at least the sum of seven hundred thousand pesos shall be appropriated every year thereafter, beginning with the next succeeding fiscal year, out of any funds in the National Treasury not otherwise appropriated, for the continued support of the College."}},{"id":"PH-H3872-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President and the Board of Regents of the University of the Philippines, on recommendation of the Head of the College of Public Administration, shall appoint and fix the Compensation of the faculty, and other personnel of the College, any law to the contrary notwithstanding."}},{"id":"PH-H3872-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The different department, agencies and subdivisions, as well as government-owned or controlled corporations of the Philippine Government are hereby authorized to utilize savings from any item or items of their appropriations to cover fees and other necessary expenses as may be required of their scholars attending the academic programs of the College."}},{"id":"PH-H3872-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The College of Public Administration may for the purpose of this Act obtain the services of professional or technical personnel of any agency of the Philippine Government or from the private sector, to provide instruction, perform research, and such other activities as may be necessary. The College of Public Administration may impose and collect fees for projects requiring consultancy, feasibility studies, research and other services, which fees shall accrue to a revolving fund of the College. Such personnel or agencies involved in these undertakings shall be given honorarium or paid on a contractual basis by the University of the Philippines upon recommendation of the Head of the College of Public Administration, any law to the contrary notwithstanding."}},{"id":"PH-H3872-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Making the College of Public Administration of the University of the Philippines a More Effective Training Institution","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3873"] = {"id":"PH-H3873","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4912_1967.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Two Hundred Thousand Pesos for Operational and Incidental Expenses of the First Asian Foreign Service Course to be Held in Manila and Baguio, Philippines, from August 4, 1967 to September 29, 1967, Under the Joint Auspices of the Government of the Republic of the Philippines and the Eastern Regional Organization for Public Administration (EROPA)","orig":"An Act Appropriating the Sum of Two Hundred Thousand Pesos for Operational and Incidental Expenses of the First Asian Foreign Service Course to be Held in Manila and Baguio, Philippines, from August 4, 1967 to September 29, 1967, Under the Joint Auspices of the Government of the Republic of the Philippines and the Eastern Regional Organization for Public Administration (EROPA)"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4912","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4912_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3873-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"It is the national policy to promote and encourage better relations among countries in the Asian region. The Philippines has taken a leadership role in promoting friendly relations.\nThe Eastern Regional Organization for Public Administration (EROPA) is a semi-governmental regional organization for the promotion of better systems and practices of governmental administration and has been active in promoting such working relations for the promotion of good government as a vehicle for the economic and social development of the region. The Philippines is a charter member of EROPA. The other state members are Australia, Republic of China, Iran, Japan, Republic of Korea, Malaysia, Pakistan, Thailand and the Republic of Vietnam. The headquarters of the organization are located in Manila.\nUpon the recommendation of the Executive Council and the General Assembly of EROPA as its meeting in December, 1966, in Tehran, Iran, the Philippines was chosen as the site of First Asian Foreign Service Course.\nThe Philippine Government, through the Department of Foreign Affairs has accepted the honor conferred on it by the EROPA Fourth General Assembly as the site selected for the holding of the course.\nParticipants to the course will be senior foreign service officers of some experience from the ministries of foreign affairs of the governments of the countries in the EROPA region, to study and analyze selected problems of foreign relations, with a view of attaining a deeper understanding of Asian affairs and the position of Asia in a community of nations, to provide the opportunity for improving knowledge and skills required by modern diplomacy and for broadening the outlook of foreign relations with a sense of development and to promote understanding among participants.\nOn the basis of the experience gained in the conducting of the course, it is expected that a center for diplomatic training among countries in Asia will be established.\nThe First Asian Foreign Service Course will be held in Manila and Baguio from August 4 to September 29, 1967. The Civil Service Commission has accepted the responsibility of providing the leadership for the conduct of the course, together with the Department of Foreign Affairs.\nThe Course will be held under the joint auspices of the Philippine Government through the Department of Foreign Affairs and the EROPA. The Civil Service Commission and the Department of Foreign Affairs will provide secretarial and other expert technical facilities."}},{"id":"PH-H3873-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operational and incidental expenses of the First Asian Foreign Service Course to be held in Manila and Baguio, Philippines, from the fourth day of August to the twenty-ninth day of September, nineteen hundred and sixty-seven, under the joint auspices of the Government of the Republic of the Philippines and the Eastern Regional Organization for Public Administration (EROPA)."}},{"id":"PH-H3873-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Foreign Affairs may, for the purpose of this Act, obtain the services of professional or technical personnel from abroad or from any agency or the Philippine Government as well as from the private sectors to provide instruction, perform research, and undertake such other activities as may be necessary. Such personnel will be given honoraria at rates fixed by the Organizing Committee of the First Asian Foreign Service Course."}},{"id":"PH-H3873-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55"};
  FT["PH-H3874"] = {"id":"PH-H3874","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4913_1967.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"将菲律宾国会两院 1967 年 3 月 16 日第 1 号与第 3 号决议提出的宪法修正案提交菲律宾人民批准的法案","en":"An Act Submitting to the Filipino People for Approval the Amendments to the Constitution of the Philippines Proposed by the Congress of the Philippines in Resolutions of Both Houses Numbered One and Three Adopted on March Sixteen, Nineteen Hundred and Sixty-Seven","orig":"An Act Submitting to the Filipino People for Approval the Amendments to the Constitution of the Philippines Proposed by the Congress of the Philippines in Resolutions of Both Houses Numbered One and Three Adopted on March Sixteen, Nineteen Hundred and Sixty-Seven"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4913","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4913_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3874-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The amendments to the Constitution of the Philippines proposed by the Congress of the Philippines in Resolutions of both Houses Numbered One and Three, Both adopted on March sixteen, nineteen hundred and sixty- seven, shall be submitted to the people for approval at the general election which shall be held on November fourteen, nineteen hundred and sixty-seven, in accordance with the provisions of this Act."}},{"id":"PH-H3874-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amendments shall be published in three consecutive issues of the Official Gazette at least twenty days prior to the election. A printed copy thereof shall be posted in a conspicuous place in every municipality, city and provincial office building and in every polling place not later than October fourteen, nineteen hundred and sixty-seven, and shall remain posted therein until after the election. At least five copies of the said amendments shall be kept in each polling place to be made available for examination by the qualified electors during election day. When practicable, copies in the principal native languages, as may be determined by the Commission on Elections, shall be kept in each polling places. The Commission on Elections shall make available copies of said amendments in English, Spanish and, whenever practicable, in the principal native languages, for free distribution."}},{"id":"PH-H3874-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The provisions of Republic Act Numbered One hundred eighty, as amended, otherwise known as the Revised Election Code, insofar as they are not inconsistent herewith, are hereby made applicable to the election provided for in this Act."}},{"id":"PH-H3874-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The ballots which shall be used in the election for the approval of said amendments shall be printed in English and Pilipino and shall be in the size and form prescribed by the Commission on Elections: Provided, however, That at the back of said ballot there shall be printed in full Resolutions of Both Houses of Congress Numbered One and three, both adopted on March sixteen, nineteen hundred and sixty-seven, proposing the amendments; Provided, further, That the questionnaire appearing on the face of the ballot shall be as follows:\nAre you in favor of the proposed amendment to Section five of Article VI of our Constitution printed at the back of this ballot?\nAre you in favor of the proposed amendment to Section sixteen of Article VI of our Constitution printed at the back of this ballot?\nTo vote for the approval of the proposed amendments, the voter shall write the word \"Yes\" or its equivalent in Pilipino or in the local dialect in the blank space after each question; to vote for the rejection thereof, he shall write the word \"No\" or its equivalent in Pilipino or in the local dialect."}},{"id":"PH-H3874-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The boards of election inspectors shall prepare and sign four copies of the returns of the citizens in their respective polling places on a form to be prescribed by the Commission on Elections. One copy shall be deposited in the ballot box for valid ballots, and the three copies shall be delivered to the respective municipal treasurers, who shall immediately forward, by registered mail, one copy to the Commission on Elections, one copy of the Secretary of the Senate, and one copy to the Secretary of the House of Representatives.\nWithin thirty days after the opening of the third regular session of the Sixth Congress of the Philippines, the Senate and House of Representatives shall hold a joint session, canvass the returns, and certify the result thereof."}},{"id":"PH-H3874-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The sum of one million pesos is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry into effect the provisions of this Act."}},{"id":"PH-H3874-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967"}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Submitting to the Filipino People for Approval the Amendments to the Constitution of the Philippines Proposed by the Congress of the Philippines in Resolutions of Both Houses Numbered One and Three Adopted on March Sixteen, Nineteen Hundred and Sixty-Seven","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3875"] = {"id":"PH-H3875","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4914_1967.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"规定选举出席菲律宾国会两院 1967 年 3 月 16 日决议授权的制宪会议代表并举行该会议的法案","en":"An Act Providing for the Election of Delegates to, and the Holding Of, the Constitutional Convention Authorized by Resolution of Both Houses of the Congress of the Philippines, Adopted on March Sixteen, Nineteen Hundred and Sixty-Seven","orig":"An Act Providing for the Election of Delegates to, and the Holding Of, the Constitutional Convention Authorized by Resolution of Both Houses of the Congress of the Philippines, Adopted on March Sixteen, Nineteen Hundred and Sixty-Seven"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4914","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4914_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3875-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Constitutional Convention, authorized by Resolution of Both Houses Numbered Two of the Congress of the Philippines, adopted on March sixteen, nineteen hundred and sixty-seven, shall be composed of two delegates from each representative district who shall have the same qualifications as those required of Members of the House of Representatives."}},{"id":"PH-H3875-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The election of delegates to the Convention shall be held on the second Tuesday in November, nineteen hundred and sixty-seven in accordance with the provisions of the Revised Election Code. The certificate of candidacy of a candidate for delegate shall state that he possesses all the qualifications required of Members of the House of Representatives and shall be filed in the same manner as that provided by the Revised Election Code with respect to candidates for the House of Representatives."}},{"id":"PH-H3875-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The provisions of the Revised Election Code, as amended, and Republic Act Numbered Thirty-five hundred eighty-eight, insofar as they are not inconsistent with the provisions of this Act, shall apply in the election of delegates to the Constitutional Convention."}},{"id":"PH-H3875-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The office of Delegate shall be compatible with any other public office: Provided, That delegates who do not receive any salary from the Government shall be entitled to a per diem of fifty pesos for every day of attendance in the convention or any of its committees: Provided, however, That a delegate who is receiving salary from the Government may choose to receive his salary or the per diem herein provided: Provided, further, That every delegate shall be entitled to the necessary traveling expenses to and from his place of residence when attending sessions of the convention or of its committee."}},{"id":"PH-H3875-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The convention shall meet in the session hall of the House of Representatives on June first, nineteen hundred and seventy-one, at ten o'clock in the morning."}},{"id":"PH-H3875-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Senate and House of Representatives shall place at the disposal of the convention such personnel, premises, and furniture thereof as can, in their judgment, be spared without detriment to the public service, without cost, refund or additional pay."}},{"id":"PH-H3875-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The laws relative to parliamentary immunity of the Member of the Congress shall be applicable to the delegates of the Constitutional Convention, and the penalties imposed in Articles one hundred forty-three, one hundred forty-four and one hundred forty-five of the Revised Penal Code, as amended, for offenses defined therein against the Congress of the Philippines, its committees or subcommittees, or its Members shall likewise apply if such offenses are committed against the Constitutional Convention, its committees or subcommittees, or the delegates thereto."}},{"id":"PH-H3875-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"There is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of fourteen million pesos for the holding of the elections of delegates to the Constitutional Convention, and six million pesos for the expenses of said convention."}},{"id":"PH-H3875-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Separability Clause. If for by reason any section or provision of this Act shall be held to be unconstitutional or invalid, no other section or provision of this Act shall be affected thereby."}},{"id":"PH-H3875-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967"}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Election of Delegates to, and the Holding Of, the Constitutional Convention Authorized by Resolution of Both Houses of the Congress of the Philippines, Adopted on March Sixteen, Nineteen Hundred and Sixty-Seven","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3876"] = {"id":"PH-H3876","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4915_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Fifteen Million Pesos to Defray the Expenses of the National Government in Connection With, and Incidental to, the Elections of Elective Provincial, City, Municipal and Municipal District Officials and Eight Senators to be Held on the Second Tuesday of November, Nineteen Hundred Sixty Seven","orig":"An Act Appropriating the Sum of Fifteen Million Pesos to Defray the Expenses of the National Government in Connection With, and Incidental to, the Elections of Elective Provincial, City, Municipal and Municipal District Officials and Eight Senators to be Held on the Second Tuesday of November, Nineteen Hundred Sixty Seven"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4915","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4915_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3876-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of fifteen million pesos to be spent under the exclusive authority of the Commission on Elections, for payment of expenses which the National Government may incur in connection with, and incidental to, the holding of the elections on the second Tuesday of November, nineteen hundred and sixty-seven, for all elective provincial, city, municipal and municipal district officials, and for eight senators: Provided, That this appropriation shall be immediately available to the Commission on Elections for expenditure before July one, nineteen hundred and sixty-seven and shall continue to be available after June thirty, nineteen hundred and sixty-eight and until all the expenses of said elections shall have been paid, and shall be given priority of release upon request of the Commission on Elections: Provided, further, That the Commission on Elections is authorized to spend such sums as may be necessary for the implementation of the registration law provided under Republic Act Numbered Three thousand five hundred and eighty-eight, as amended."}},{"id":"PH-H3876-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55"};
  FT["PH-H3877"] = {"id":"PH-H3877","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4916_1967.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"授予 Eagle 广播公司在菲律宾设立、维护和运营无线电广播与电视站的特许经营权法案","en":"An Act Granting the Eagle Broadcasting Corporation a Franchise to Establish, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines","orig":"An Act Granting the Eagle Broadcasting Corporation a Franchise to Establish, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines","vi":"Đạo luật cấp quyền khai thác cho Eagle Broadcasting Corporation để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh và truyền hình tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ Eagle Broadcasting Corporation เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงและวิทยุโทรทัศน์ในฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada Eagle Broadcasting Corporation untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio dan televisi di Filipina","ms":"Akta memberikan francais kepada Eagle Broadcasting Corporation untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio dan televisyen di Filipina"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 4916","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4916_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3877-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, as well as of Act Numbered Three thousand eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Three thousand nine hundred ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, not inconsistent with this Act, Eagle Broadcasting Corporation, is hereby granted a franchise to establish, maintain and operate radio broadcasting and television stations in the Philippines."}},{"id":"PH-H3877-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date said station shall be put in operation, and is granted upon the express condition that the same shall be void unless the construction of at least one radio broadcasting station or one television station be began within one year from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H3877-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This franchise is likewise made upon the express condition that the grantee shall provide adequate public service time to enable the government, through its stations, to reach the population on important issues, shall assist in the function of public information and education, shall conform to the ethics of honest enterprise, and shall not use its stations for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health and morals, or incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H3877-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee’s radio broadcasting and television stations shall not be put in actual operation until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used under this franchise and issued to the grantee license for such use."}},{"id":"PH-H3877-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The radio broadcasting station and television stations of the grantee shall be so constructed and operated and the wave lengths so selected as to avoid interference with existing radio stations and television stations and to permit the expansion of the grantee’s service."}},{"id":"PH-H3877-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace or order, to cause the closing of said stations or to authorize the temporary use and operation thereof by any department of the government without compensating the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H3877-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall be liable to pay the same taxes unless exempted therefrom, on its real estate, buildings and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay. It shall be liable further to pay all other taxes as provided in the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H3877-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceptance of this franchise shall be given in writing by the grantee within six months after the approval of this Act. When so accepted, the grantee shall be empowered to exercise the privileges granted thereby."}},{"id":"PH-H3877-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall file a bond in the amount of ten thousand pesos to guarantee the full compliance with fulfillment of the conditions under which this franchise is granted. If after two years from the date of acceptance of this franchise, the grantee shall have fulfilled said conditions or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications."}},{"id":"PH-H3877-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play, act, or scene or other matter to be broadcast and/or telecast from its stations; but if any speech, play act or scene or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene or other matter: Provided, That the grantee, during any broadcast and/or telecast may cut off from the air the speech, play, act or scene or other matter being broadcast and/or telecast if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral."}},{"id":"PH-H3877-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this franchise may be sold, transferred or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and as completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H3877-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H3877-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Eagle Broadcasting Corporation a Franchise to Establish, Maintain and Operate Radio Broadcasting and Television Stations in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3878"] = {"id":"PH-H3878","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4917_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"规定私营企业雇员退休金不得被扣押、征收、执行或课征任何税的法案","en":"An Act Providing that Retirement Benefits of Employees of Private Firms Shall not be Subject to Attachment, Levy, Execution, or Any Tax Whatsoever","orig":"An Act Providing that Retirement Benefits of Employees of Private Firms Shall not be Subject to Attachment, Levy, Execution, or Any Tax Whatsoever"},"level":"law","status":"active","topics":["labor","tax"],"docNumber":"Republic Act No. 4917","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4917_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3878-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law to the contrary notwithstanding, the retirement benefits received by officials and employees of private firms, whether individual or corporate, in accordance with a reasonable private benefit plan maintained by the employer shall be exempt from all taxes and shall not be liable to attachment, garnishment, levy or seizure by or under any legal or equitable process whatsoever except to pay a debt of the official or employee concerned to the private benefit plan or that arising from liability imposed in a criminal action: Provided, That the retiring official or employee has been in the service of the same employer for at least ten (10) years and is not less than fifty years of age at the time of his retirement: Provided, further, That the benefits granted under this Act shall be availed of by an official or employee only once: Provided, finally, That in case of separation of an official or employee from the service of the employer due to death, sickness or other physical disability or for any cause beyond the control of the said official or employee, any amount received by him or by his heirs from the employer as a consequence of such separation shall likewise be exempt as hereinabove provided.\nAs used in this Act, the term \"reasonable private benefit plan\" means a pension, gratuity, stock bonus or profit sharing plan maintained by an employer for the benefit of some or all of his officials and employees, wherein contributions are made by such employer or officials and employees, or both, for the purpose of distributing to such officials and employees the earnings and principal of the fund thus accumulated, and wherein it is provided in said plan that at no time shall any part of the corpus or income of the fund be used for, or be diverted to, any purpose other than for the exclusive benefit of the said officials and employees."}},{"id":"PH-H3878-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967"}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing that Retirement Benefits of Employees of Private Firms Shall not be Subject to Attachment, Levy, Execution, or Any Tax Whatsoever","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3879"] = {"id":"PH-H3879","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4918_1967.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订《修订选举法典》第46条与第48条的法案","en":"An Act to Amend Sections Forty-Six and Forty-Eight of the Revised Election Code","orig":"An Act to Amend Sections Forty-Six and Forty-Eight of the Revised Election Code","vi":"Đạo luật sửa đổi các Điều 46 và 48 của Bộ luật Bầu cử","th":"พระราชบัญญัติแก้ไขเพิ่มเติมมาตรา 46 และ 48 แห่งประมวลกฎหมายการเลือกตั้ง","id":"Undang-Undang mengubah Pasal 46 dan 48 Kitab Undang-Undang Pemilihan","ms":"Akta meminda Seksyen 46 dan 48 Kanun Pilihan Raya"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4918","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4918_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3879-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section forty-six of Republic Act Numbered One hundred eighty, otherwise known as the Revised Election Code, is amended to read as follows:\n\"Sec. 46. Prohibited Collections of Funds. — It shall be unlawful for any person to hold balls, lottery, beauty contests, entertainments or cinematographic, or theatrical, or other performances during one hundred twenty days immediately preceding a regular or special election, for the purpose of raising funds for benefit purposes or for an election campaign, or for the support of any candidate; and no person or organization, whether civic or religious, shall directly or indirectly solicit and/or accept from any candidate for public office, or from his campaign manager, agent or representative, any gift, contribution or donation in cash or in kind during the aforementioned period: Provided, That normal and customary religious dues and/or contributions, such as religious stipends, tithes or collections on Sundays and/or other designated collection days, are excluded from this prohibition.\""}},{"id":"PH-H3879-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section forty eight of Republic Act Numbered One hundred eighty, otherwise known as the Revised Election Code, is amended to read as follows:\n\"Sec. 48. Limitation upon expenses of candidates. — No candidate shall spend for his election campaign more than the total amount of emoluments for one year attached to the office for which he is a candidate: Provided, that in no case shall any candidate, or his campaign manager, agent or representative, within one hundred twenty days immediately preceding a regular or thirty days before a special election, directly or indirectly, make any donation, contribution, or gift in cash or in kind, or undertake and/or contribute to the construction of roads, bridges, schoolhouses, puericulture centers, medical clinics and hospitals, churches or chapels, cement pavement for dancing, or any other structure for public use or for the use of any religious or civic organization: Provided, further, That normal and customary religious dues and/or contributions, such as religious stipends, tithes and/or collections on Sundays and/or other designated collection days, as well as periodic payments for legitimate scholarships established before the prohibited period, are excluded from this prohibition.\""}},{"id":"PH-H3879-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Sections Forty-Six and Forty-Eight of the Revised Election Code","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3880"] = {"id":"PH-H3880","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4919_1967.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予 Monja Securities Corporation 在菲律宾境内建设、维护和运营私人固定点对点、海岸、陆基、航空与陆上移动无线电台的临时许可的法案","en":"An Act Granting Monja Securities Corporation a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point, Coastal, Land-Based, Aeronautical and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting Monja Securities Corporation a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point, Coastal, Land-Based, Aeronautical and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","vi":"Đạo luật cấp giấy phép tạm thời cho Monja Securities Corporation để xây dựng, duy trì và vận hành trạm vô tuyến cố định điểm-điểm, ven biển, trên mặt đất, hàng không và di động mặt đất tư nhân để nhận và truyền thông tin vô tuyến tại Philippines","th":"พระราชบัญญัติให้ใบอนุญาตชั่วคราวแก่ Monja Securities Corporation ในการก่อสร้าง บำรุงรักษา และดำเนินการสถานีวิทยุแบบจุดต่อจุดประจำที่、ชายฝั่ง、ภาคพื้นดิน、การบินและเคลื่อนที่ภาคพื้นดินของเอกชนสำหรับรับและส่งการสื่อสารทางวิทยุในฟิลิปปินส์","id":"Undang-Undang memberikan izin sementara kepada Monja Securities Corporation untuk membangun, memelihara, dan mengoperasikan stasiun radio titik-ke-titik tetap, pesisir, berbasis darat, penerbangan dan mudah alih darat swasta untuk penerimaan dan pengiriman komunikasi radio di Filipina","ms":"Akta memberikan permit sementara kepada Monja Securities Corporation untuk membina, menyelenggarakan dan mengendalikan stesen radio titik-ke-titik tetap, pesisir, berasas darat, penerbangan dan mudah alih darat persendirian untuk penerimaan dan penghantaran komunikasi radio di Filipina"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 4919","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4919_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3880-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Monja Securities Corporation a temporary permit to construct, maintain and operate at such places as the grantee may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point, coastal, land-based, aeronautical and land-mobile radio stations for the reception and transmission of wireless messages on radiotelegraph or radiotelephone, each station to be provided with radio transmitting and radio receiving apparatus."}},{"id":"PH-H3880-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar services at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction or installation of said stations be begun within one year from the date of approval of this Act and completed within two years from said date."}},{"id":"PH-H3880-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, its successors or assigns, shall not engage in domestic business of telecommunications in the Philippines without further special assent from the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, maintain and operate private fixed point-to-point, coastal, land-based, aeronautical, and land-mobile radio stations in such places within the Philippines as the interest of the grantee may justify."}},{"id":"PH-H3880-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H3880-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H3880-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to person, caused by the construction or operation of its radio stations."}},{"id":"PH-H3880-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H3880-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, is authorized to operate its private fixed point-to-point, coastal, land-based, aeronautical and land-mobile radio stations in the medium frequency, high frequency, and very high frequency that may be assigned to it by the Secretary of Public Works and Communications."}},{"id":"PH-H3880-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"That grantee shall not lease, transfer, grant the usufruct of, nor sell or assign this temporary permit, or the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, company or corporation organized for the same purpose without the approval of the Congress of the Philippines first had. Any corporation to which this temporary permit may be sold, transferred, or assigned shall be subject to the corporation laws of the Philippines, now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if temporary permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H3880-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H3880-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H3880-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Monja Securities Corporation a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point, Coastal, Land-Based, Aeronautical and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3881"] = {"id":"PH-H3881","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4920_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将马尼拉市桑帕洛克区埃科诺米亚街更名为比森特·G·克鲁斯街的法案","en":"An Act Changing the Name of Economia Street in the District of Sampaloc, City of Manila, to Vicente G. Cruz","orig":"An Act Changing the Name of Economia Street in the District of Sampaloc, City of Manila, to Vicente G. Cruz","vi":"Đạo luật đổi tên Đường Economia tại Quận Sampaloc, Thành phố Manila thành Vicente G. Cruz","th":"พระราชบัญญัติเปลี่ยนชื่อถนน Economia ในเขต Sampaloc เมือง Manila เป็น Vicente G. Cruz","id":"Undang-Undang Mengubah Nama Jalan Economia di Distrik Sampaloc, Kota Manila menjadi Vicente G. Cruz","ms":"Akta Menukar Nama Jalan Economia di Daerah Sampaloc, Bandar Manila kepada Vicente G. Cruz"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4920","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4920_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3881-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Economia street in the District of Sampaloc, City of Manila, is hereby changed to Vicente G. Cruz."}},{"id":"PH-H3881-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Economia Street in the District of Sampaloc, City of Manila, to Vicente G. Cruz","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3882"] = {"id":"PH-H3882","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4921_1967.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"将 Dr. Jose R. Reyes 纪念医院癌症检测与诊断中心扩及癌症治疗与研究并为其拨款的法案","en":"An Act Extending the Scope of the Cancer Detection and Diagnostic Center of the Dr. Jose R. Reyes Memorial Hospital to Include also Cancer Treatment and Research, and Appropriating Funds Therefor","orig":"An Act Extending the Scope of the Cancer Detection and Diagnostic Center of the Dr. Jose R. Reyes Memorial Hospital to Include also Cancer Treatment and Research, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 4921","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4921_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3882-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The scope of the existing Cancer Detection and Diagnostic Center of the Dr. Jose R. Reyes Memorial Hospital, Department of Health, is hereby extended to include the following functions, in addition to its present limited function of cancer detection and diagnosis:\na) To render all forms of cancer treatment to patients, (surgery, radiation therapy, cancer chemotherapy, hormone therapy);\nb) To extend its services of cancer detection, diagnosis, and treatment particularly to indigent cancer patients;\nc) To undertake the thorough instruction and training of medical and para-medical personnel in the field of oncology;\nd) To utilize any of the services and facilities of the Dr. Jose R. Reyes Memorial Hospital which are necessary for the cancer center in order that it may carry out its functions properly;\ne) To undertake clinical studies and researches for better control and management of cancer among Filipinos;\nf) To operate a cancer registry within the center and to regularly submit its statistical data to the Office of the Department of Health, which is in charge of compiling the Official Cancer Registry in the Philippines;\ng) To establish liaison with other instrumentalities and agencies, both government and private, engaged in cancer work; and\nh) To perform such other functions as may be necessary to carry into effect the purpose of this Act."}},{"id":"PH-H3882-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The official title of the Cancer Detection and Diagnostic Center of the Dr. Jose R. Reyes Memorial Hospital shall be changed to \"The Cancer Center, Dr. Jose R. Reyes Memorial Hospital\", Department of Health."}},{"id":"PH-H3882-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The incumbent Head and the Staff of the existing Cancer Center of the Dr. Jose R. Reyes Memorial Hospital shall retain their respective positions and items in the Cancer Center."}},{"id":"PH-H3882-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Appointments to new positions in the Cancer Center shall be made in accordance with law and only according to merit and technical fitness as provided for by the qualifying rules and regulations of the Department of Health and the Civil Service Commission."}},{"id":"PH-H3882-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The powers, functions, and duties of all officers under the Department of Health on the cancer detection, diagnosis and therapy, together with all their equipment, supplies, records, files, personnel and balance of appropriations are transferred to the Cancer Center of the Dr. Jose R. Reyes Memorial Hospital."}},{"id":"PH-H3882-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Any income of the Cancer Center shall be retained by it in its revolving fund for expansion and improvement of its various services especially for the indigent cancer patients."}},{"id":"PH-H3882-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The Cancer Center of the Dr. Jose R. Reyes Memorial Hospital shall serve as the model for similar Cancer Centers to be established in five Medical Centers and Regional Training Hospitals throughout the Philippines, the number to be increased as the demand for service also increases."}},{"id":"PH-H3882-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The sum of five hundred thousand pesos is hereby authorized to be appropriated in the Annual General Appropriations Act to be expended exclusively to carry out the purposes of this Act, including the construction of an office and the purchase of equipment."}},{"id":"PH-H3882-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"All Acts, executive orders, rules and regulations or parts thereof, inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H3882-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Extending the Scope of the Cancer Detection and Diagnostic Center of the Dr. Jose R. Reyes Memorial Hospital to Include also Cancer Treatment and Research, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3883"] = {"id":"PH-H3883","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4922_1967.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"授予 Ruben A. So 在马实巴特省 Monreal 市镇安装、维护和运营电灯、热力与动力系统的特许权法案","en":"An Act Granting Ruben A. So a Franchise to Install, Maintain and Operate an Electric Light, Heat and Power System in the Municipality of Monreal, Province of Masbate","orig":"An Act Granting Ruben A. So a Franchise to Install, Maintain and Operate an Electric Light, Heat and Power System in the Municipality of Monreal, Province of Masbate","vi":"Đạo luật cấp quyền khai thác cho Ruben A. So để xây dựng, lắp đặt, vận hành và duy trì hệ thống điện tại thị xã Monreal, tỉnh Masbate","th":"พระราชบัญญัติให้สัมปทานแก่ Ruben A. So เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบไฟฟ้าในเทศบาล Monreal, จังหวัด Masbate","id":"Undang-Undang memberikan waralaba kepada Ruben A. So untuk membangun, memasang, mengoperasikan, dan memelihara sistem tenaga listrik di Kotamadya Monreal, Provinsi Masbate","ms":"Akta memberikan francais kepada Ruben A. So untuk membina, memasang, mengendalikan dan menyelenggara sistem tenaga elektrik di Perbandaran Monreal, Wilayah Masbate"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 4922","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4922_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3883-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, there is hereby granted to Ruben A. So, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to install, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the limits of the Municipality of Monreal, Province of Masbate."}},{"id":"PH-H3883-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H3883-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In consideration of the franchise and rights hereby granted, the grantee shall pay a franchise tax equal to five per centum of the gross earnings under this franchise, three per centum of which shall accrue to the National Government and two per centum to the municipality where the franchise is being operated."}},{"id":"PH-H3883-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"It is hereby expressly provided that in the event the Government should decide to maintain and operate for itself the plant and enterprise herein authorized, the grantee shall surrender his franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H3883-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Ruben A. So a Franchise to Install, Maintain and Operate an Electric Light, Heat and Power System in the Municipality of Monreal, Province of Masbate","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3884"] = {"id":"PH-H3884","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4923_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将马斯巴特省 Aroroy市镇某村的名称变更为San Isidro村的法案","en":"An Act Changing the Name of a Certain Barrio in the Municipality of Aroroy, Province of Masbate, to Barrio San Isidro","orig":"An Act Changing the Name of a Certain Barrio in the Municipality of Aroroy, Province of Masbate, to Barrio San Isidro","vi":"Đạo luật đổi tên a Certain Barrio tại Thị trấn Aroroy, Tỉnh Masbate thành Barrio San Isidro","th":"พระราชบัญญัติเปลี่ยนชื่อ a Certain Barrio ในเทศบาล Aroroy, จังหวัด Masbate เป็นบารริโอ San Isidro","id":"Undang-Undang mengubah nama a Certain Barrio di Kotamadya Aroroy, Provinsi Masbate menjadi Barrio San Isidro","ms":"Akta menukar nama a Certain Barrio di Perbandaran Aroroy, Wilayah Masbate menjadi Barrio San Isidro"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4923","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4923_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3884-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Barrio Tete in the Municipality of Aroroy, Province of Masbate, is charged to Barrio San Isidro."}},{"id":"PH-H3884-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of a Certain Barrio in the Municipality of Aroroy, Province of Masbate, to Barrio San Isidro","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3885"] = {"id":"PH-H3885","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4924_1967.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"授予 Jesus B. Arevalo 在马实巴特省 San Fernando 市镇安装、维护和运营电灯、热力与动力系统的特许权法案","en":"An Act Granting Jesus B. Arevalo a Franchise to Install, Maintain and Operate an Electric Light, Heat and Power System in the Municipality of San Fernando, Province of Masbate","orig":"An Act Granting Jesus B. Arevalo a Franchise to Install, Maintain and Operate an Electric Light, Heat and Power System in the Municipality of San Fernando, Province of Masbate","vi":"Đạo luật cấp quyền khai thác cho Jesus B. Arevalo để xây dựng, lắp đặt, vận hành và duy trì hệ thống điện tại thị xã San Fernando, tỉnh Masbate","th":"พระราชบัญญัติให้สัมปทานแก่ Jesus B. Arevalo เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบไฟฟ้าในเทศบาล San Fernando, จังหวัด Masbate","id":"Undang-Undang memberikan waralaba kepada Jesus B. Arevalo untuk membangun, memasang, mengoperasikan, dan memelihara sistem tenaga listrik di Kotamadya San Fernando, Provinsi Masbate","ms":"Akta memberikan francais kepada Jesus B. Arevalo untuk membina, memasang, mengendalikan dan menyelenggara sistem tenaga elektrik di Perbandaran San Fernando, Wilayah Masbate"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 4924","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4924_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3885-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, there is hereby granted to Jesus B. Arevalo, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to install, maintain and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat and/or power for sale within the limits of the Municipality of San Fernando, Province of Masbate."}},{"id":"PH-H3885-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure electric heat and power from the National Power Corporation, the latter is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H3885-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In consideration of the franchise and rights hereby granted, the grantee shall pay a franchise tax equal to five per centum of the gross earnings under this franchise, three per centum of which shall accrue to the National Government and two per centum to the municipality where the franchise is being operated."}},{"id":"PH-H3885-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"It is hereby expressly provided that in the event the Government should decide to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender his franchise and turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H3885-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Jesus B. Arevalo a Franchise to Install, Maintain and Operate an Electric Light, Heat and Power System in the Municipality of San Fernando, Province of Masbate","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3886"] = {"id":"PH-H3886","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4925_1967.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"授予 Teresita S. Rosales 在 Calbayog 市建设、维护和运营制冰厂与冷藏库的特许权法案","en":"An Act Granting Teresita S. Rosales a Franchise to Construct, Maintain and Operate an Ice Plant and Cold Storage in the City of Calbayog","orig":"An Act Granting Teresita S. Rosales a Franchise to Construct, Maintain and Operate an Ice Plant and Cold Storage in the City of Calbayog","vi":"Đạo luật cấp đặc quyền cho Teresita S. Rosales để xây dựng, duy trì và vận hành nhà máy nước đá và kho lạnh tại Thành phố Calbayog","th":"พระราชบัญญัติให้สัมปทานแก่ Teresita S. Rosales ในการก่อสร้าง บำรุงรักษา และดำเนินการโรงงานน้ำแข็งและห้องเย็นในเมือง Calbayog","id":"Undang-Undang memberikan konsesi kepada Teresita S. Rosales untuk membangun, memelihara, dan mengoperasikan pabrik es dan penyimpanan dingin di Kota Calbayog","ms":"Akta memberikan konsesi kepada Teresita S. Rosales untuk membina, menyelenggarakan dan mengendalikan kilang ais dan stor sejuk di Bandar Calbayog"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 4925","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4925_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3886-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in this Act and in Commonwealth Act Numbered One hundred forty-six, as amended, and to the provisions of the Constitution, there is granted to Teresita S. Rasales, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an ice plant and cold storage, for the purpose of manufacturing ice for distribution and sale, and for supplying cold storage in the City of Calbayog and to charge and collect a schedule of prices and rates therefor which schedule shall at all times be subject to regulation by the Public Service Commission or its legal successor."}},{"id":"PH-H3886-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee shall manufacture and supply ice up to the limit of the capacity of her plant, said limit to be determined by the Public Service Commission, and sell the same at rates to be determined by the said Public Service Commission."}},{"id":"PH-H3886-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect, and the grantee shall, whenever the Public Service Commission shall determine that public interest reasonably requires it, change or alter any of such apparatus and appurtenances at grantee’s expense."}},{"id":"PH-H3886-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"If the grantee shall not commence the construction of the ice plant and cold storage within two years from the approval of this Act, unless prevented by an act of God or force majeure, martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee’s control, this franchise shall become null and void."}},{"id":"PH-H3886-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise is granted with the understanding and upon the condition that it shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H3886-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The books, records and accounts of the grantee shall always be open to the inspection of the Auditor General or his authorized representatives, and it shall be the duty of the grantee to submit to the Auditor General quarterly reports in duplicate showing the gross receipts for the quarter past."}},{"id":"PH-H3886-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In the event of any competing person, natural or juridical, receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of such competing person."}},{"id":"PH-H3886-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Teresita S. Rosales a Franchise to Construct, Maintain and Operate an Ice Plant and Cold Storage in the City of Calbayog","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3887"] = {"id":"PH-H3887","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4926_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为马斯巴特省增设两名助理省检察官职位，并为此修订《行政法典》第1674条（经修正）的法案","en":"An Act Granting Two Additional Positions of Assistant Provincial Fiscal in the Province of Masbate, Amending for the Purpose Section Sixteen Hundred Seventy-Four the Administrative Code, as Amended","orig":"An Act Granting Two Additional Positions of Assistant Provincial Fiscal in the Province of Masbate, Amending for the Purpose Section Sixteen Hundred Seventy-Four the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4926","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4926_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3887-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section sixteen hundred seventy-four of the Administrative Code, as amended, relative to the number of assistant provincial fiscals in the Province of Masbate, is further amended to read as follows:\n\"Masbate, four assistant provincial fiscals;\""}},{"id":"PH-H3887-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Two Additional Positions of Assistant Provincial Fiscal in the Province of Masbate, Amending for the Purpose Section Sixteen Hundred Seventy-Four the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3888"] = {"id":"PH-H3888","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4927_1967.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在山区省Bayag市镇设立国立工业农业中学，名称为Apayao国立工业农业中学，并授权为此拨款的法案","en":"An Act Providing for the Establishment of a National Industrial Agricultural High School in the Municipality of Bayag, Mountain Province, to be Known as Apayao National Industrial Agricultural High School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a National Industrial Agricultural High School in the Municipality of Bayag, Mountain Province, to be Known as Apayao National Industrial Agricultural High School, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 4927","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4927_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3888-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the supervision of the Director of Vocational Education a national industrial agricultural high school in the Municipality of Bayag, Mountain Province, to be known as Apayao National Industrial Agricultural High School. The site of the said school shall be determined by the Municipal Council of Bayag in consultation with the Director of Vocational Education."}},{"id":"PH-H3888-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Director of Vocational Education shall issue such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H3888-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the fiscal year nineteen hundred sixty-seven. Thereafter, the necessary funds needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3888-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a National Industrial Agricultural High School in the Municipality of Bayag, Mountain Province, to be Known as Apayao National Industrial Agricultural High School, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3889"] = {"id":"PH-H3889","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4928_1967.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Conner市","en":"An Act Establishing a Vocational High School in the Municipality of Conner, Mountain Province, to be Known as Conner Vocational High School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a Vocational High School in the Municipality of Conner, Mountain Province, to be Known as Conner Vocational High School, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Trường Trung học Dạy nghề Conner tại Đô thị Conner, Tỉnh Mountain Province, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาอาชีวศึกษา Conner ในเทศบาล Conner จังหวัด Mountain Province และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Sekolah Menengah Kejuruan Conner di Kotamadya Conner, Provinsi Mountain Province, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Sekolah Menengah Vokasional Conner di Perbandaran Conner, Wilayah Mountain Province, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4928","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4928_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3889-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Vocational Education, a vocational high school in the Municipality of Conner, Mountain Province, to be known as Conner Vocational High School."}},{"id":"PH-H3889-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon recommendation of the Director of Vocational Education, the President of the Philippines shall set aside and reserve such portion of the public lands located within the Municipality of Conner, Mountain Province, as may be necessary and convenient for the establishment of the school site."}},{"id":"PH-H3889-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said school for the first year. Thereafter, the necessary sums for said purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H3889-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55"};
