  FT["PH-H3904"] = {"id":"PH-H3904","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4943_1967.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立San Jose Del Monte市","en":"An Act Establishing a Community Hospital in Sapang Palay, Municipality of San Jose Del Monte, Province of Bulacan, to be Known as Sapang Palay Community Hospital, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a Community Hospital in Sapang Palay, Municipality of San Jose Del Monte, Province of Bulacan, to be Known as Sapang Palay Community Hospital, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Cộng đồng Sapang Palay tại Đô thị San Jose Del Monte, Tỉnh Bulacan, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลชุมชน Sapang Palay ในเทศบาล San Jose Del Monte จังหวัด Bulacan และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Komunitas Sapang Palay di Kotamadya San Jose Del Monte, Provinsi Bulacan, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Komuniti Sapang Palay di Perbandaran San Jose Del Monte, Wilayah Bulacan, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 4943","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4943_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3904-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Medical Services, A community hospital in Sapang Palay, Municipality of San Jose del Monte, Province of Bulacan, to be known as the Sapang Palay Community Hospital."}},{"id":"PH-H3904-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-seven. Thereafter, such sums as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3904-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55"};
  FT["PH-H3905"] = {"id":"PH-H3905","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4944_1967.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定在布拉干省Marilao市镇设立国立职业学校，名称为Marilao国立职业学校，并授权为此拨款的法案","en":"An Act Providing for the Establishment of a National Trade School in the Municipality of Marilao, Province of Bulacan, to be Known as Marilao National Trade School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a National Trade School in the Municipality of Marilao, Province of Bulacan, to be Known as Marilao National Trade School, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Trường Thương mại Quốc gia tại Thị trấn Marilao, Tỉnh Bulacan với tên gọi Trường Thương mại Marilao Quốc gia, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงเรียนการค้าแห่งชาติในเทศบาล Marilao จังหวัด Bulacan ในชื่อโรงเรียนการค้า Marilao แห่งชาติ และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Sekolah Perdagangan Nasional di Kotamadya Marilao, Provinsi Bulacan dengan nama Sekolah Perdagangan Marilao Nasional, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Sekolah Perdagangan Kebangsaan di Perbandaran Marilao, Wilayah Bulacan dengan nama Sekolah Perdagangan Marilao Kebangsaan, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["trade","education"],"docNumber":"Republic Act No. 4944","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4944_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3905-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Vocational Education, a national trade school in the Municipality of Marilao, Province of Bulacan, to be known as Marilao National Trade School. Courses of secondary level shall be offered in said school."}},{"id":"PH-H3905-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the fiscal year nineteen hundred sixty-seven. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3905-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a National Trade School in the Municipality of Marilao, Province of Bulacan, to be Known as Marilao National Trade School, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3906"] = {"id":"PH-H3906","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4945_1967.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在北三宝颜省Piñan市镇设立社区医院，名称为Piñan社区医院，并授权为此拨款的法案","en":"An Act Establishing a Community Hospital in the Municipality of Piñan, Province of Zamboanga del Norte, to be Known as Piñan Community Hospital, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a Community Hospital in the Municipality of Piñan, Province of Zamboanga del Norte, to be Known as Piñan Community Hospital, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Cộng đồng tại Đô thị Piñan, Tỉnh Zamboanga del Norte với tên gọi Bệnh viện Cộng đồng Piñan, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลชุมชน ในเทศบาล Piñan จังหวัด Zamboanga del Norte ในชื่อ โรงพยาบาลชุมชน Piñan และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Komunitas di Kotamadya Piñan, Provinsi Zamboanga del Norte dengan nama Rumah Sakit Komunitas Piñan, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Komuniti di Perbandaran Piñan, Wilayah Zamboanga del Norte dengan nama Hospital Komuniti Piñan, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 4945","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4945_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3906-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Medical Services, a community hospital in the Municipality of Piñan, Province of Zamboanga, to be known as Piñan Community Hospital."}},{"id":"PH-H3906-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-seven. Thereafter, such sums as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3906-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a Community Hospital in the Municipality of Piñan, Province of Zamboanga del Norte, to be Known as Piñan Community Hospital, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3907"] = {"id":"PH-H3907","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4946_1967.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Jose Abad Santos市","en":"An Act Establishing an Emergency Hospital in the Municipality of Jose Abad Santos, Province of Davao, to be Known as Jose Abad Santos Emergency Hospital and Authorizing the Appropriation of One Hundred Fifty Thousand Pesos Therefor","orig":"An Act Establishing an Emergency Hospital in the Municipality of Jose Abad Santos, Province of Davao, to be Known as Jose Abad Santos Emergency Hospital and Authorizing the Appropriation of One Hundred Fifty Thousand Pesos Therefor","vi":"Đạo luật thành lập Bệnh viện Cấp cứu Jose Abad Santos tại Đô thị Jose Abad Santos, Tỉnh Davao, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลฉุกเฉิน Jose Abad Santos ในเทศบาล Jose Abad Santos จังหวัด Davao และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Gawat Darurat Jose Abad Santos di Kotamadya Jose Abad Santos, Provinsi Davao, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Kecemasan Jose Abad Santos di Perbandaran Jose Abad Santos, Wilayah Davao, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 4946","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4946_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3907-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established in the Municipality of Jose Abad Santos, Province of Davao, an emergency hospital to be known as Jose Abad Santos Emergency Hospital, which shall be under the supervision of the Director of the Medical Services, Department of Health. The site of said hospital shall be provided for by the Municipal Council of the Municipality of Jose Abad Santos in consultation with the Director of Medical Services."}},{"id":"PH-H3907-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall promulgate such rules and regulations as may be necessary to carry into effect the purposes of this Act."}},{"id":"PH-H3907-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-seven. Such sums as may be necessary for its operation and maintenance in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H3907-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55"};
  FT["PH-H3908"] = {"id":"PH-H3908","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_4947_1967.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Mati市","en":"An Act Establishing a National Hospital in the Municipality of Mati, Province of Davao, to be Known as Davao Oriental National Hospital, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a National Hospital in the Municipality of Mati, Province of Davao, to be Known as Davao Oriental National Hospital, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Davao Oriental Quốc gia tại Đô thị Mati, Tỉnh Davao, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาล Davao Oriental แห่งชาติ ในเทศบาล Mati จังหวัด Davao และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Davao Oriental Nasional di Kotamadya Mati, Provinsi Davao, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Davao Oriental Kebangsaan di Perbandaran Mati, Wilayah Davao, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 4947","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_4947_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3908-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Medical Services, a national hospital in the Municipality of Mati, Province of Davao, to be known as Davao Oriental National Hospital."}},{"id":"PH-H3908-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-seven. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3908-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55"};
  FT["PH-H3909"] = {"id":"PH-H3909","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5003_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第2423号共和国法，要求东内格罗斯省Larena市镇的Larena国立职业中学同时开设职业课程与普通课程的法案","en":"An Act Amending Republic Act Numbered Twenty-Four Hundred Twenty-Three by Requiring the Larena National Vocational School in the Municipality of Larena, Province of Negros Oriental, to Offer Both Vocational and General Courses","orig":"An Act Amending Republic Act Numbered Twenty-Four Hundred Twenty-Three by Requiring the Larena National Vocational School in the Municipality of Larena, Province of Negros Oriental, to Offer Both Vocational and General Courses","vi":"Đạo luật sửa đổi Đạo luật Cộng hòa số 2423","th":"พระราชบัญญัติแก้ไขเพิ่มเติมพระราชบัญญัติแห่งสาธารณรัฐที่ 2423","id":"Undang-Undang mengubah Undang-Undang Republik No. 2423","ms":"Akta meminda Akta Republik No. 2423"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5003","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5003_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3909-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered twenty-four hundred twenty-three is hereby amended to read as follows:\n\"Sec. 1. The Larena Sub-Provincial High School in the Municipality of Larena, Province of Negros Oriental, is hereby converted into a national vocational school to be known as the Larena National Vocational School. The said school shall be under the supervision of the Bureau of Public Schools and subject to the provisions of the school law. General and vocational courses of secondary level shall be offered in the said school.\""}},{"id":"PH-H3909-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Republic Act Numbered Twenty-Four Hundred Twenty-Three by Requiring the Larena National Vocational School in the Municipality of Larena, Province of Negros Oriental, to Offer Both Vocational and General Courses","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3910"] = {"id":"PH-H3910","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5004_1967.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"授予 Banaag 企业公司在东明多洛省 Pinamalayan 市镇安装、维护和运营制冰厂与冷藏库特许权的法案","en":"An Act Granting the Banaag Enterprises, Inc. a Franchise to Install, Maintain and Operate Iceplant and Cold Storage in the Municipality of Pinamalayan, Province of Oriental Mindoro","orig":"An Act Granting the Banaag Enterprises, Inc. a Franchise to Install, Maintain and Operate Iceplant and Cold Storage in the Municipality of Pinamalayan, Province of Oriental Mindoro"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5004","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5004_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3910-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in this Act and in Commonwealth Act Numbered One hundred forty-six, as amended, and to the provisions of the Constitution, there is granted to the Banaag Enterprises, Inc., for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an ice plant and cold storages in the Municipality of Pinamalayan, Province of Oriental Mindoro, for the purpose of manufacturing ice for distribution and sale in those municipalities covered by its certificate of public convenience, and for supplying cold storage in the whole Province of Oriental Mindoro and to charge and collect a schedule of prices and rates therefor which schedule shall at all times be subject to regulation by the Public Service Commission or its legal successors."}},{"id":"PH-H3910-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee shall manufacture and supply ice up to limit of the capacity of its plant, said limit to be determined by the Public Service Commission, and sell the same at rates to be determined by the said Commission."}},{"id":"PH-H3910-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect, and the grantee shall, whenever the Public Service Commission shall determine that public interest reasonably requires it, change or later any of its apparatus and appurtenances at grantee’s expense."}},{"id":"PH-H3910-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"If the grantee shall not commence the construction of the ice plant and cold storage within six years from the approval of this Act, unless prevented by an act of God or force majeure, martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee’s control, this franchise shall become null and void."}},{"id":"PH-H3910-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise is granted with the understanding and upon the condition that it shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H3910-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The franchise hereby granted is subject to the provisions of Commonwealth Act Numbered One hundred forty-six, as amended, only with respect to the fixing of rates."}},{"id":"PH-H3910-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In consideration of the franchise hereby granted, the grantee shall pay to the Municipal Treasurer of Pinamalayan in the Province of Oriental Mindoro a tax equivalent to one per centum of the gross earning of its business during the life of this franchise for every quarter past in lieu of all other taxes, fees of any kind, nature or description levied, established or collected by any authority, municipal, provincial, city or national, now or in the future and on its building, machinery and equipment."}},{"id":"PH-H3910-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The books, records and accounts of the grantee shall always be open to the inspection of the Auditor General or his authorized representatives, and it shall be the duty of the grantee to submit to the Auditor General quarterly reports in duplicate showing the gross receipts for the quarter past."}},{"id":"PH-H3910-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"In the event of any competing person, natural or juridical, receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of such competing person."}},{"id":"PH-H3910-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Banaag Enterprises, Inc. a Franchise to Install, Maintain and Operate Iceplant and Cold Storage in the Municipality of Pinamalayan, Province of Oriental Mindoro","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3911"] = {"id":"PH-H3911","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5005_1967.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"授予 Esperanza Lazaro 在黎刹省 Malabon 市镇 Dampalit 村建设、维护和运营制冰厂并销售所生产冰的特许权法案","en":"An Act Granting Esperanza Lazaro a Franchise to Construct, Maintain and Operate an Ice Plant in Barrio Dampalit, Municipality of Malabon, Province of Rizal","orig":"An Act Granting Esperanza Lazaro a Franchise to Construct, Maintain and Operate an Ice Plant in Barrio Dampalit, Municipality of Malabon, Province of Rizal","vi":"Đạo luật cấp đặc quyền cho Esperanza Lazaro để xây dựng, duy trì và vận hành nhà máy nước đá tại Barrio Dampalit, Thị trấn Malabon, Tỉnh Rizal","th":"พระราชบัญญัติให้สัมปทานแก่ Esperanza Lazaro ในการก่อสร้าง บำรุงรักษา และดำเนินการโรงงานน้ำแข็งในบาริโอ Dampalit เทศบาล Malabon จังหวัด Rizal","id":"Undang-Undang memberikan konsesi kepada Esperanza Lazaro untuk membangun, memelihara, dan mengoperasikan pabrik es di Barrio Dampalit, Kotamadya Malabon, Provinsi Rizal","ms":"Akta memberikan konsesi kepada Esperanza Lazaro untuk membina, menyelenggarakan dan mengendalikan kilang ais di Barrio Dampalit, Perbandaran Malabon, Wilayah Rizal"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5005","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5005_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3911-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in this Act and in Commonwealth Act Numbered One hundred forty-six, as amended, and to the provisions of the Constitution, there is hereby granted to Esperanza Lazaro, for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an ice plant in Barrio Dampalit, Municipality of Malabon, Province of Rizal, for the purpose of manufacturing ice for distribution and sale in the said municipality and to charge and collect a schedule of prices and rates therefor which schedule shall, at all times, be subject to regulation by the Public Service Commission or its legal successor."}},{"id":"PH-H3911-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee shall manufacture and supply ice up to the limit of the capacity of her plant, said limit to be determined by the Public Service Commission, and sell the same at rates to be determined by the said Commission."}},{"id":"PH-H3911-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect, and the grantee shall, whenever the Public Service Commission shall determine that public interest reasonably requires it, change or alter any of her apparatus and appurtenances at grantee’s expense."}},{"id":"PH-H3911-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"If the grantee shall not commence the construction of the ice plant within two years from the approval of this Act, unless prevented by an act of God or force majeure, martial law, riot, civil commotion usurpation by a military power or any other cause beyond the grantee’s control, this franchise shall become null and void."}},{"id":"PH-H3911-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise is granted with the understanding and upon the condition that it shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H3911-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The books, records and accounts of the grantee shall always be open to the inspection of the Auditor General or his authorized representatives, and it shall be the duty of the grantee to submit to the Auditor General quarterly reports in duplicate showing the gross receipts for the quarter past."}},{"id":"PH-H3911-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In the event of any competing person, natural or juridical, receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become part of the terms hereof and shall operate equally in favor of the grantee as in the case of such competing person."}},{"id":"PH-H3911-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Esperanza Lazaro a Franchise to Construct, Maintain and Operate an Ice Plant in Barrio Dampalit, Municipality of Malabon, Province of Rizal","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3912"] = {"id":"PH-H3912","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5006_1967.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在伊洛伊洛省设立Badiangan市镇的法案","en":"An Act Creating the Municipality of Badiangan in the Province of Iloilo","orig":"An Act Creating the Municipality of Badiangan in the Province of Iloilo","vi":"Đạo luật thành lập Thị trấn Badiangan tại Tỉnh Iloilo","th":"พระราชบัญญัติจัดตั้งเทศบาล Badiangan ในจังหวัด Iloilo","id":"Undang-Undang membentuk Kotamadya Badiangan di Provinsi Iloilo","ms":"Akta mewujudkan Perbandaran Badiangan di Wilayah Iloilo"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5006","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5006_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3912-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barrios Badiangan, Agusipan, Astorga, Bingauan, Bitaoyan, Botong, Budiaue, Cabanga-an, Cabayoyan, Calanzanan, Catubig, Guinauahan, Ilongbukid, Indorahan, Iniligan, Latauan, Linayuan, Mainguit, Malublub, Manaolan, Mapili Grande, Mapili Sangjo, Odiongan, San Julian, Sari-ri, Sianon, Sinwagan, Talaba, Tamacol, Teneclan and Tina in the Municipality of Janiuay, Province of Iloilo, are separated from said municipality and constituted into a distinct and independent municipality, to be known as the Municipality of Badiangan.\nThe seat of government of the new municipality shall be in Barrio Badiangan. The Municipality of Badiangan shall have the following boundaries;\n\"The boundary lines between the Municipality of Janiuay and the Municipality of Badiangan starts from the northern portion of the municipality from Municipal Boundary Monument (MBM) No. 33 of Lambunao and Janiuay to Barrio Boundary Monument (BBM) No. 104 of the barrio of Sarawag and Mapili Grande; then to BBM No. 102 of the barrio of Sarawag-Patongpatong and Mapili Grande-Botong; then to BBM No. 96 of the barrio of Patongpatong-Madong and Botong; then to BBM No. 75 of the barrio of Madong and Botong-Calanzanan; then to BBM No. 76 of the barrio of Madong and Calanzanan; then to BBM No. 78 along the Magapa River to BBM No. 79 of the barrio of Matag-ob-Gibolo and Calanzanan; then to BBM No. 60 of the barrio of Gibolo and Calanzalan-Sianon; then to BBM No. 59 of the barrio of Gibolo-Damires and Sianon; then to BBM No. 48 of the barrio of Damires and Sianon-Iniligan; then to BBM No. 50 of the barrio Damires and Iniligan-Teneclan; then to BBM No. 51 of the barrio of Damires and Teneclan-Catubig; then to BBM No. 52 of the barrio of Damires-Tinioan and Catubig; then to BBM No. 16 of the barrio Tinioan and Catubig; then to BBM No. 15 of the barrio of Tinioan-Cabantog and Catubig; then to BBM No. 14 of the barrio Cabantog-Caranas and Catubig Bitaoyan; then to BBM No. 17 of the barrio Bitaoyan and Caranas and along the municipal boundary of Janiuay and Pototan from MBM No. 3 to MBM No. 2 of the Janiuay Cadastre No. 226.\""}},{"id":"PH-H3912-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Municipality of Badiangan shall acquire corporate existence upon the election and qualification of the first mayor, vice-mayor and councilors in the next general elections for local officials. For election purposes, the municipal officials of the mother municipality charged with the election duties in accordance with the Revised Election Code shall hold office until the first officials shall have been elected and qualified."}},{"id":"PH-H3912-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Badiangan in the Province of Iloilo","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3913"] = {"id":"PH-H3913","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5007_1967.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"授权拨款25000比索援助伊洛伊洛省New Lucena市镇购置市政厅与公共广场占用场地，包括该场地的改良","en":"An Act Authorizing the Appropriation of Twenty-Five Thousand Pesos as Aid to the Municipality of New Lucena, Province of Iloilo, for the Purchase of the Site Occupied by the Town Hall and Public Plaza, Including the Improvement of Said Site","orig":"An Act Authorizing the Appropriation of Twenty-Five Thousand Pesos as Aid to the Municipality of New Lucena, Province of Iloilo, for the Purchase of the Site Occupied by the Town Hall and Public Plaza, Including the Improvement of Said Site"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5007","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5007_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3913-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of twenty-five thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, as aid to the Municipality of New Lucena, Province of Iloilo, for the purchase of the site occupied by the town hall and public plaza, including the improvement of said site."}},{"id":"PH-H3913-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Appropriation of Twenty-Five Thousand Pesos as Aid to the Municipality of New Lucena, Province of Iloilo, for the Purchase of the Site Occupied by the Town Hall and Public Plaza, Including the Improvement of Said Site","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3914"] = {"id":"PH-H3914","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5008_1967.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"授予 Philippine Seeds，Inc. 在菲律宾境内建设、维护和运营私人固定点对点、海岸、陆基、航空与陆上移动无线电台的临时许可的法案","en":"An Act Granting Philippine Seeds, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point, Coastal, Land-Based, Aeronautical and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting Philippine Seeds, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point, Coastal, Land-Based, Aeronautical and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","vi":"Đạo luật cấp giấy phép tạm thời cho Philippine Seeds, Inc. để xây dựng, duy trì và vận hành trạm vô tuyến cố định điểm-điểm, ven biển, trên mặt đất, hàng không và di động mặt đất tư nhân để nhận và truyền thông tin vô tuyến tại Philippines","th":"พระราชบัญญัติให้ใบอนุญาตชั่วคราวแก่ Philippine Seeds, Inc. ในการก่อสร้าง บำรุงรักษา และดำเนินการสถานีวิทยุแบบจุดต่อจุดประจำที่、ชายฝั่ง、ภาคพื้นดิน、การบินและเคลื่อนที่ภาคพื้นดินของเอกชนสำหรับรับและส่งการสื่อสารทางวิทยุในฟิลิปปินส์","id":"Undang-Undang memberikan izin sementara kepada Philippine Seeds, Inc. untuk membangun, memelihara, dan mengoperasikan stasiun radio titik-ke-titik tetap, pesisir, berbasis darat, penerbangan dan mudah alih darat swasta untuk penerimaan dan pengiriman komunikasi radio di Filipina","ms":"Akta memberikan permit sementara kepada Philippine Seeds, Inc. untuk membina, menyelenggarakan dan mengendalikan stesen radio titik-ke-titik tetap, pesisir, berasas darat, penerbangan dan mudah alih darat persendirian untuk penerimaan dan penghantaran komunikasi radio di Filipina"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 5008","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5008_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3914-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Philippine Seeds, Inc., a temporary permit to construct, establish, maintain and operate in the Philippines, and/or at such places as the grantee may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point. coastal, land based, aeronautical and land mobile radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H3914-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said radio stations or any of them on lands of the public domain upon such terms and conditions as he may prescribe."}},{"id":"PH-H3914-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee and is granted upon the express condition that the same shall be void unless the construction of at least one of the said stations be begun within one year from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H3914-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall not engage in domestic business of telecommunication in the Philippines without further special assent of the Congress of the Philippines it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, establish, maintain and operate said radio stations at such places within the Philippines as the interest of the grantee and of its trade and business may justify."}},{"id":"PH-H3914-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This temporary permit shall not take effect until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wavelengths to be used thereunder, but the grantee may use the international distress frequency of eight thousand two hundred eighty kilocycles whenever necessary."}},{"id":"PH-H3914-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"No fees are chargeable as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H3914-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H3914-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H3914-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, or the rights or privileges acquired thereunder to any persons, natural or juridical, nor merge with any other persons, without the approval of the Congress of the Philippines first had. Any person, natural or juridical, to which this temporary permit may be sold, transferred or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person to which this temporary permit is sold, transferred or assigned, shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to such persons."}},{"id":"PH-H3914-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall file a bond in the amount of ten thousand pesos to warranty the full compliance with and fulfillment of the conditions under which the franchise is granted. If after two years from the date of acceptance of this franchise, the grantee shall have fulfilled said conditions or soon thereafter, the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications."}},{"id":"PH-H3914-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H3914-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This temporary permit shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H3914-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Philippine Seeds, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point, Coastal, Land-Based, Aeronautical and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3915"] = {"id":"PH-H3915","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5009_1967.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授予 Transport Contractors，Inc. 在菲律宾境内建设、维护和运营私人固定点对点、陆基与陆上移动无线电台的临时许可的法案","en":"An Act Granting Transport Contractors, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land-Based and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting Transport Contractors, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land-Based and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","vi":"Đạo luật cấp giấy phép tạm thời cho Transport Contractors, Inc. để xây dựng, duy trì và vận hành trạm vô tuyến cố định điểm-điểm, trên mặt đất và di động mặt đất tư nhân để nhận và truyền thông tin vô tuyến tại Philippines","th":"พระราชบัญญัติให้ใบอนุญาตชั่วคราวแก่ Transport Contractors, Inc. ในการก่อสร้าง บำรุงรักษา และดำเนินการสถานีวิทยุแบบจุดต่อจุดประจำที่、ภาคพื้นดินและเคลื่อนที่ภาคพื้นดินของเอกชนสำหรับรับและส่งการสื่อสารทางวิทยุในฟิลิปปินส์","id":"Undang-Undang memberikan izin sementara kepada Transport Contractors, Inc. untuk membangun, memelihara, dan mengoperasikan stasiun radio titik-ke-titik tetap, berbasis darat dan mudah alih darat swasta untuk penerimaan dan pengiriman komunikasi radio di Filipina","ms":"Akta memberikan permit sementara kepada Transport Contractors, Inc. untuk membina, menyelenggarakan dan mengendalikan stesen radio titik-ke-titik tetap, berasas darat dan mudah alih darat persendirian untuk penerimaan dan penghantaran komunikasi radio di Filipina"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5009","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5009_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3915-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Transport Contractors, Inc., its successors or assigns, a temporary permit to construct, maintain and operate in the Philippines, at Manila and at such places as the said corporation may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point and land-based and land-mobile radio stations for the reception and transmission of wireless messages on radiotelegraphy and radiotelephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H3915-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction or installation of said stations be begun within one year from the date of the approval of this Act and be completed within two years from said date."}},{"id":"PH-H3915-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, its successors or assigns, shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure the grantee the right to construct, install, maintain and operate private fixed point-to-point and land-based and land-mobile radio stations in such places within the Philippines as the interest of the grantee may justify, as well as to enable it to better serve the public in the dissemination of news and events of national interest."}},{"id":"PH-H3915-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H3915-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H3915-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands, or action arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H3915-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H3915-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, is authorized to operate its private fixed point-to-point and land-based and land-mobile radio stations in the medium frequency, high frequency, and very high frequency that may be assigned to it by the Secretary of Public Works and Communications."}},{"id":"PH-H3915-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, calamity or disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use or possession thereof by any department of the Government upon its just compensation."}},{"id":"PH-H3915-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H3915-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Transport Contractors, Inc. a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land-Based and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
