  FT["PH-H3927"] = {"id":"PH-H3927","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1967/ra_5021_1967.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在伊洛伊洛省设立繁育站，名称为Tigbauan繁育站，并授权为此拨付所需资金的法案","en":"An Act Establishing a Breeding Station in the Province of Iloilo, to be Known as Tigbauan Breeding Station, and Authorizing the Appropriation of the Necessary Funds Therefor","orig":"An Act Establishing a Breeding Station in the Province of Iloilo, to be Known as Tigbauan Breeding Station, and Authorizing the Appropriation of the Necessary Funds Therefor","vi":"Đạo luật thành lập Trạm Nhân giống Tigbauan tại Tỉnh Iloilo, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งสถานีเพาะพันธุ์ Tigbauan ในจังหวัด Iloilo และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Stasiun Pembibitan Tigbauan di Provinsi Iloilo, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Stesen Pembiakan Tigbauan di Wilayah Iloilo, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5021","issuingBody":"Congress of the Philippines","promulgatedDate":"1967-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1967/ra_5021_1967.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3927-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Animal Industry, a breeding station in the Province of Iloilo, on a suitable public or private land of not less than thirty hectares which may be reserved or acquired for the purpose. It shall be known as Tigbauan Breeding Station."}},{"id":"PH-H3927-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of the funds of the National Treasury not otherwise appropriated, said sum to be expended by the Director of Animal Industry, subject to the approval of the Secretary of Agriculture and Natural Resources, for the purchase of breeding animals, supplies and materials; for the construction of buildings, a water system, sheds, corrals and other structures; salaries and wages; and for other expenses needed to carry out the purposes of this Act for the fiscal year nineteen hundred and sixty-seven. Thereafter, the necessary sums for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3927-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1967."}}],"pack":"ph-p55","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a Breeding Station in the Province of Iloilo, to be Known as Tigbauan Breeding Station, and Authorizing the Appropriation of the Necessary Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
